Вы можете для этого случая использовать @Bean. application.properties: springboot.field=field MySuperCustomProperties.class: @Configuration
public class MySuperCustomProperties {

    @Bean
    public SomeClass someProperty( @Value("${springboot.field}") String field ) {
        SomeClass someClass = new SomeClass();
        someClass.setField(field);
        return someClass;
    }

} SomeClass.class: public class SomeClass {

    private String field;

    public String getField() {
        return field;
    }

    public void setField(String field) {
        this.field = field;
    }

} Application.class: @SpringBootApplication
public class Application implements CommandLineRunner {

    @Autowired
    private SomeClass someClass;

    public static void main(String[] args) {
        SpringApplication.run(Application.class);
    }

    @Override
    public void run(String... args) throws Exception {
        System.out.println(someClass.getField());
    }

}

